import math

def quad_form(A, x):
    return sum(x[i] * A[i][j] * x[j] for i in range(len(x)) for j in range(len(x)))

A = [[2, 0], [0, 1]]
values = [quad_form(A, [math.cos(math.radians(d)), math.sin(math.radians(d))]) for d in range(0, 360, 15)]
print(min(values) > 0)  # True

def height(x, y):
    return 2 * x * x + y * y  # x^T A x for A = [[2, 0], [0, 1]]

print(height(0, 0), height(1, 0), height(0, 1))  # 0 2 1: lowest at the origin

def quad_form(A, x):
    return sum(x[i] * A[i][j] * x[j] for i in range(len(x)) for j in range(len(x)))

B = [[1, 0], [0, -1]]
print(quad_form(B, [1, 0]), quad_form(B, [0, 1]))  # 1 -1: a saddle
